@Test
void serializersAreRegisteredAsExpected() throws Exception {
    final var authenticationProviderMock = mock(AuthenticationProvider.class);
    var defaultRequestAdapter = new DefaultRequestAdapter(authenticationProviderMock);
    assertEquals("", defaultRequestAdapter.getBaseUrl());
    // validate
    var serializerCount = SerializationWriterFactoryRegistry.defaultInstance.contentTypeAssociatedFactories.size();
    var deserializerCount = ParseNodeFactoryRegistry.defaultInstance.contentTypeAssociatedFactories.size();
    // four serializers present
    assertEquals(4, serializerCount);
    // three deserializers present
    assertEquals(3, deserializerCount);
    var serializerKeys = SerializationWriterFactoryRegistry.defaultInstance.contentTypeAssociatedFactories.keySet();
    var deserializerKeys = ParseNodeFactoryRegistry.defaultInstance.contentTypeAssociatedFactories.keySet();
    assertTrue(serializerKeys.contains("application/json"));
    assertTrue(deserializerKeys.contains(// Serializer and deserializer present for
    "application/json"));
    // application/json
    assertTrue(serializerKeys.contains("text/plain"));
    assertTrue(deserializerKeys.contains(// Serializer and deserializer present for text/plain
    "text/plain"));
    assertTrue(serializerKeys.contains("application/x-www-form-urlencoded"));
    assertTrue(deserializerKeys.contains(// Serializer and deserializer
    "application/x-www-form-urlencoded"));
    // present for
    // application/x-www-form-urlencoded
    assertTrue(serializerKeys.contains(// Serializer present for multipart/form-data
    "multipart/form-data"));
}

